Content:
.k-sr-only {
    position: absolute;
    left: -1px;
    width: 1px;
    height: 1px;
    overflow: hidden;
}

.k-theme-test-class,
.k-common-test-class {
    opacity: 0;
}

.k-body {
    font-size: var(--kendo-font-size, inherit);
    font-family: var(--kendo-font-family, inherit);
    line-height: var(--kendo-line-height, normal);
    font-weight: var(--kendo-font-weight, normal);
    letter-spacing: var(--kendo-letter-spacing, normal);
    color: var(--kendo-body-text, initial);
    background-color: var(--kendo-body-bg, initial);
    margin: 0;
}

.k-hstack, .k-hbox {
    display: flex;
    flex-flow: row nowrap;
}

.k-vstack, .k-vbox {
    display: flex;
    flex-flow: column nowrap;
}

.k-spacer, .k-flex {
    flex: 1 1 auto;
}

.k-spacer-sized {
    flex: none;
}

.k-float-wrap::after, .k-floatwrap::after {
    content: "";
    display: block;
    clear: both;
}

.k-flex-layout {
    display: flex;
}

.k-grid-layout {
    display: grid;
}

.k-separator {
    width: auto;
    height: 0;
    border-width: 1px 0 0;
    border-style: solid;
    border-color: inherit;
    display: block;
    flex-grow: 0 !important;
    flex-shrink: 0 !important;
    align-self: stretch;
}

.k-separator-horizontal,
.k-vstack > .k-separator,
.k-vbox > .k-separator {
    width: auto;
    height: 0;
    border-width: 1px 0 0;
}

.k-separator-vertical,
.k-hstack > .k-separator,
.k-hbox > .k-separator {
    width: 0;
    height: auto;
    border-width: 0 0 0 1px;
}

hr.k-separator {
    margin: 0;
    padding: 0;
}

.k-hidden {
    display: none !important;
}

.k-rtl {
    direction: rtl;
}

[hidden] {
    display: none !important;
}

script {
    display: none !important;
}

.k-disabled,
.k-widget[disabled],
.k-disabled {
    outline: none;
    cursor: default;
    color: var(--kendo-disabled-text, inherit);
    border-color: var(--kendo-disabled-border, inherit);
    pointer-events: none;
    box-shadow: none;
}

    .k-disabled .k-link,
    .k-widget[disabled] .k-link,
    .k-disabled .k-link {
        cursor: default;
        outline: 0;
    }

.k-hr {
    margin-block: 16px;
    padding: 0;
    height: 0;
    border-width: 1px 0 0;
    border-style: solid;
    border-color: var(--kendo-component-border, inherit);
    display: block;
    float: none;
    clear: both;
}

.k-d-flex-row > .k-hr {
    margin: 0;
    width: 0;
    height: auto;
    border-width: 0 0 0 1px;
    flex: 0 0 auto;
}

.k-d-flex-col > .k-hr {
    margin: 0;
    flex: 0 0 auto;
}

.k-sprite {
    display: inline-block;
    width: 1rem;
    height: 1rem;
    overflow: hidden;
    background-repeat: no-repeat;
    font-size: 0;
    line-height: 0;
    text-align: center;
}

.k-image {
    display: inline-block;
}

.k-reset {
    margin: 0;
    padding: 0;
    border-width: 0;
    outline: 0;
    text-decoration: none;
    font: inherit;
    list-style: none;
}

kendo-sortable {
    display: block;
}

.k-link,
.k-link:hover {
    color: inherit;
    text-decoration: none;
    outline: 0;
    cursor: pointer;
}

.k-content {
    outline: 0;
}

.k-centered {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

.k-no-click {
    pointer-events: none;
}

.k-pdf-export-shadow {
    position: absolute;
    overflow: hidden;
    left: -15000px;
    width: 14400px;
}

.kendo-pdf-hide-pseudo-elements::before,
.kendo-pdf-hide-pseudo-elements::after {
    display: none !important;
}

.k-dirty {
    margin: 0;
    padding: 0;
    width: 0;
    height: 0;
    border-width: 3px;
    border-style: solid;
    border-block-start-color: currentColor;
    border-block-end-color: transparent;
    border-inline-start-color: transparent;
    border-inline-end-color: currentColor;
    position: absolute;
    inset-block-start: 0;
    inset-inline-end: 0;
}

.k-loading-mask,
.k-loading-image,
.k-loading-color {
    width: 100%;
    height: 100%;
    box-sizing: border-box;
    position: absolute;
    top: 0;
    left: 0;
}

    .k-loading-mask *,
    .k-loading-mask *::before,
    .k-loading-mask *::after, .k-loading-mask::before, .k-loading-mask::after,
    .k-loading-image *,
    .k-loading-image *::before,
    .k-loading-image *::after,
    .k-loading-image::before,
    .k-loading-image::after,
    .k-loading-color *,
    .k-loading-color *::before,
    .k-loading-color *::after,
    .k-loading-color::before,
    .k-loading-color::after {
        box-sizing: border-box;
    }

.k-loading-mask {
    z-index: 100;
}

    .k-loading-mask.k-opaque .k-loading-color {
        opacity: 1;
    }

.k-loading-text {
    text-indent: -4000px;
    text-align: center;
    position: absolute;
    color: currentColor;
}

.k-loading-image {
    z-index: 2;
    color: currentColor;
}

.k-loading-color {
    background-color: #ffffff;
    opacity: 0.3;
}

.k-i-loading {
    width: 1em;
    height: 1em;
    line-height: 1;
    display: inline-flex;
    flex-flow: row nowrap;
    align-items: center;
    justify-content: center;
    vertical-align: middle;
    position: relative;
    background-color: transparent;
    box-sizing: border-box;
    color: currentColor;
}

    .k-i-loading::before, .k-i-loading::after {
        box-sizing: border-box;
    }

    .k-i-loading::before,
    .k-i-loading::after,
    .k-loading-image::before,
    .k-loading-image::after {
        position: absolute;
        top: 50%;
        left: 50%;
        display: inline-block;
        content: "";
        box-sizing: inherit;
        border-radius: 50%;
        border-width: .05em;
        border-style: solid;
        border-color: currentColor;
        border-top-color: transparent;
        border-bottom-color: transparent;
        background-color: transparent;
    }

.k-icon.k-i-loading::before,
.k-icon.k-i-loading::after {
    content: "";
}

.k-i-loading::before,
.k-loading-image::before {
    margin-top: -.5em;
    margin-left: -.5em;
    width: 1em;
    height: 1em;
    animation: k-loading-animation .7s linear infinite;
}

.k-i-loading::after,
.k-loading-image::after {
    margin-top: -.25em;
    margin-left: -.25em;
    width: .5em;
    height: .5em;
    animation: k-loading-animation reverse 1.4s linear infinite;
}

.k-loading-image::before,
.k-loading-image::after {
    content: "";
    border-width: 1px;
    border-width: clamp(0.015em, 1px, 1px);
    font-size: 4em;
}

@keyframes k-loading-animation {
    0% {
        transform: rotate(0deg);
    }

    100% {
        transform: rotate(360deg);
    }
}

.k-marquee {
    position: absolute;
    z-index: 100000;
}

.k-marquee-color,
.k-marquee-text {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
}

.k-marquee-color {
    color: #ffffff;
    background-color: var(--kendo-primary-60, #ff6358);
    border-color: var(--kendo-primary-100, rgba(0, 0, 0, 0.08));
    opacity: .6;
}

.k-marquee-text {
    color: #ffffff;
}

:root {
    --kendo-elevation-1: 0 2px 3px rgba(0, 0, 0, 0.04), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-2: 0 4px 6px rgba(0, 0, 0, 0.06), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-3: 0 6px 8px rgba(0, 0, 0, 0.08), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-4: 0 8px 10px rgba(0, 0, 0, 0.12), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-5: 0 10px 12px rgba(0, 0, 0, 0.16), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-6: 0 12px 14px rgba(0, 0, 0, 0.2), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-7: 0 14px 16px rgba(0, 0, 0, 0.24), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-8: 0 16px 18px rgba(0, 0, 0, 0.28), 0 4px 16px rgba(0, 0, 0, 0.12);
    --kendo-elevation-9: 0 32px 34px rgba(0, 0, 0, 0.32), 0 4px 16px rgba(0, 0, 0, 0.12);
}

