.k-text-selection ::selection {
    background-color: #ff6358;
    color: white;
}

.k-block,
.k-panel {
    border-radius: 4px;
    border-color: rgba(0, 0, 0, 0.08);
    color: #424242;
    background-color: #ffffff;
    padding: 0;
    border-width: 1px;
    border-style: solid;
    box-sizing: border-box;
}

    .k-block > .k-header,
    .k-panel > .k-header {
        border-top-left-radius: 4px;
        border-top-right-radius: 4px;
        border-color: rgba(0, 0, 0, 0.08);
        color: #424242;
        background-color: #fafafa;
        padding-inline: 8px;
        padding-block: 4px;
    }

    .k-block > .k-content,
    .k-panel > .k-content {
        padding-inline: 8px;
        padding-block: 4px;
    }

.k-content {
    border-color: rgba(0, 0, 0, 0.08);
    color: #424242;
    background-color: #ffffff;
}

.k-disabled,
.k-widget[disabled] {
    outline: none;
    cursor: default;
    opacity: 0.6;
    filter: grayscale(0.1);
    pointer-events: none;
    box-shadow: none;
}

    .k-disabled .k-link,
    .k-widget[disabled] .k-link {
        cursor: default;
        outline: 0;
    }

    .k-disabled [disabled],
    .k-disabled .k-disabled,
    .k-widget[disabled] [disabled],
    .k-widget[disabled] .k-disabled {
