}

.k-push-up-exit-active {
    transform: translate(0, -100%);
    transition: transform 300ms ease-in-out;
}

.k-expand-vertical-enter, .k-expand-vertical-appear {
    transform: scaleY(0);
}

.k-expand-vertical-enter-active, .k-expand-vertical-appear-active {
    transform: scaleY(1);
