}

.k-fade-exit {
    opacity: 1;
}

.k-fade-exit-active {
    opacity: 0;
    transition: opacity 500ms ease-in-out;
}

    .k-fade-exit-active + .k-fade-exit-active,
    .k-fade-enter-active + .k-fade-enter-active {
        display: none;
    }

.k-zoom-in-enter, .k-zoom-in-appear {
